export const CARD_HTML = "<!DOCTYPE html><html lang=\"he\" dir=\"rtl\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>בחירות 2026 — תשובה</title><style>:root{--paper:238 241 245;--card:255 255 255;--line:213 219 227;--ink:19 23 29;--ink-soft:74 85 99;--ink-faint:92 101 114;--accent:27 58 140;--accent-soft:230 236 248;--warn:163 78 0;--warn-soft:255 244 232;--pos:22 120 70;--neg:190 40 50;--mk-range:52 105 214;--mk-mean:0 150 70;--mk-result:220 0 30;--frame:255 255 255;--frame-ink:19 23 29;--frame-soft:74 85 99;--frame-line:213 219 227;--signal:232 119 14;--signal-ink:19 23 29;--band:19 23 29;--band-ink:244 246 248;--band-soft:184 192 204;--radius:12px;--grid:226 230 236}:root[data-theme=\"dark\"]{--paper:16 18 22;--card:26 29 35;--line:52 58 68;--ink:236 239 243;--ink-soft:176 184 196;--ink-faint:146 155 168;--accent:130 160 240;--accent-soft:30 38 62;--warn:245 160 80;--warn-soft:52 36 20;--pos:100 205 150;--neg:245 125 125;--mk-range:106 150 235;--mk-mean:60 210 120;--mk-result:255 70 80;--frame:26 29 35;--frame-ink:236 239 243;--frame-soft:176 184 196;--frame-line:52 58 68;--signal:240 140 40;--signal-ink:19 23 29;--band:38 44 56;--band-ink:236 239 243;--band-soft:176 184 196;--grid:40 45 54}@media (prefers-color-scheme: dark){:root:not([data-theme=\"light\"]){--paper:16 18 22;--card:26 29 35;--line:52 58 68;--ink:236 239 243;--ink-soft:176 184 196;--ink-faint:146 155 168;--accent:130 160 240;--accent-soft:30 38 62;--warn:245 160 80;--warn-soft:52 36 20;--pos:100 205 150;--neg:245 125 125;--mk-range:106 150 235;--mk-mean:60 210 120;--mk-result:255 70 80;--frame:26 29 35;--frame-ink:236 239 243;--frame-soft:176 184 196;--frame-line:52 58 68;--signal:240 140 40;--signal-ink:19 23 29;--band:38 44 56;--band-ink:236 239 243;--band-soft:176 184 196;--grid:40 45 54;color-scheme:dark}}\n/* כרטיס התשובה — רק מהטוקנים של האתר (DESIGN.md). הערכים עצמם נגזרים מ-src/index.css בבנייה (card/build.mjs). */\n:root { color-scheme: light; }\n:root[data-theme=\"dark\"] { color-scheme: dark; }\n* { box-sizing: border-box; }\nhtml, body { margin: 0; background: transparent; }\nbody {\n  font-family: \"Rubik\", system-ui, -apple-system, \"Segoe UI\", Arial, sans-serif;\n  font-size: 16px;\n  line-height: 1.6;\n  color: rgb(var(--ink));\n}\n.card {\n  background: rgb(var(--card));\n  border: 1px solid rgb(var(--line));\n  border-radius: var(--radius);\n  padding: 16px;\n  max-width: 100%;\n}\nbody { container-type: inline-size; }\n@container (min-width: 520px) { .card { padding: 20px; } }\n.site { margin: 0 0 4px; font-size: 13px; color: rgb(var(--ink-soft)); font-weight: 600; }\n.title { margin: 0 0 8px; font-size: 24px; line-height: 1.15; font-weight: 800; }\n.summary { margin: 0 0 12px; color: rgb(var(--ink)); }\n.sec { border-top: 1px solid rgb(var(--line)); padding-top: 12px; margin-top: 12px; }\n.heading { margin: 0 0 8px; font-size: 18px; line-height: 1.25; font-weight: 700; }\n.text { margin: 0 0 8px; max-width: 48rem; }\n.list { margin: 0; padding-inline-start: 20px; }\n.list li { margin-bottom: 4px; }\n.meta { margin: 6px 0 0; font-size: 13px; color: rgb(var(--ink-soft)); }\n.link { color: rgb(var(--accent)); font-weight: 600; text-decoration: underline; text-underline-offset: 2px; }\n.link:focus-visible, .chip:focus-visible { outline: 3px solid rgb(var(--signal)); outline-offset: 2px; }\n.tabular { font-variant-numeric: tabular-nums; }\n.numbers { display: grid; grid-template-columns: repeat(auto-fill, minmax(150px, 1fr)); gap: 12px; }\n.numbers > * { min-width: 0; }\n.tile { border: 1px solid rgb(var(--line)); border-radius: var(--radius); padding: 10px 12px; background: rgb(var(--card)); }\n.label { margin: 0; font-size: 14px; color: rgb(var(--ink-soft)); }\n.value { margin: 2px 0 0; font-size: 26px; line-height: 1.1; font-weight: 700; }\n.tablewrap { overflow-x: auto; }\n.table { width: 100%; border-collapse: collapse; font-size: 15px; }\n.table th { text-align: start; font-weight: 700; color: rgb(var(--ink-soft)); border-bottom: 1px solid rgb(var(--line)); padding: 6px 8px; }\n.table td { border-bottom: 1px solid rgb(var(--line)); padding: 6px 8px; }\n.table td.num { font-weight: 700; }\n.questions { border-top: 1px solid rgb(var(--line)); margin-top: 12px; padding-top: 12px; display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }\n.qtitle { margin: 0; width: 100%; font-size: 14px; font-weight: 700; color: rgb(var(--ink-soft)); }\n.chip {\n  font: inherit; font-size: 15px; min-height: 44px; padding: 8px 14px; border-radius: 999px; cursor: pointer;\n  border: 1px solid rgb(var(--line)); background: rgb(var(--paper)); color: rgb(var(--ink)); text-align: start;\n}\n.chip:hover { border-color: rgb(var(--accent)); }\n.foot { margin-top: 12px; padding-top: 8px; border-top: 1px solid rgb(var(--line)); display: flex; flex-wrap: wrap; justify-content: space-between; gap: 8px; font-size: 13px; color: rgb(var(--ink-soft)); }\n.footnote { margin: 0; flex: 1 1 14rem; }\n@media (prefers-reduced-motion: reduce) { * { transition: none !important; } }\n</style></head><body><main id=\"app\" aria-live=\"polite\"></main><script>// כרטיס התשובה של שרת ה-MCP (MCP Apps, מפרט 2026-01-26) — רץ בתוך המסגרת של העוזר (Claude, ChatGPT).\n// 🔴 אין לכרטיס רשת ואין לו אסימון: הוא מציג רק את התשובה ש-show_answer בדק בשרת (structuredContent).\n// 🔴 טקסט מוצג כטקסט בלבד (textContent), בלי HTML מהתשובה. קישורים נפתחים רק לאתר עצמו, דרך המארח (ui/open-link).\n(function () {\n  \"use strict\";\n  var SITE = \"https://hopetohelp.github.io/26/\";\n  var root = document.getElementById(\"app\");\n  var pending = {};\n  var nextId = 1;\n  var rendered = false;\n\n  function post(msg) { window.parent.postMessage(Object.assign({ jsonrpc: \"2.0\" }, msg), \"*\"); }\n  function request(method, params, timeout) {\n    var id = nextId++;\n    return new Promise(function (resolve, reject) {\n      var t = timeout ? setTimeout(function () { delete pending[id]; reject(new Error(\"timeout\")); }, timeout) : null;\n      pending[id] = function (err, res) { if (t) clearTimeout(t); if (err) reject(err); else resolve(res || {}); };\n      post({ id: id, method: method, params: params });\n    });\n  }\n  function el(tag, cls, text) {\n    var e = document.createElement(tag);\n    if (cls) e.className = cls;\n    if (text !== undefined && text !== null) e.textContent = String(text);\n    return e;\n  }\n  function setTheme(ctx) {\n    var t = ctx && ctx.theme;\n    if (t === \"dark\" || t === \"light\") document.documentElement.setAttribute(\"data-theme\", t);\n  }\n  function siteLink(url) { return typeof url === \"string\" && url.indexOf(SITE) === 0; }\n  function openLink(url) {\n    if (!siteLink(url)) return;\n    request(\"ui/open-link\", { url: url }).catch(function () { window.open(url, \"_blank\", \"noopener\"); });\n  }\n  function link(text, url) {\n    var a = el(\"a\", \"link\", text);\n    a.href = url;\n    a.target = \"_blank\";\n    a.rel = \"noopener\";\n    a.addEventListener(\"click\", function (ev) { ev.preventDefault(); openLink(url); });\n    return a;\n  }\n  // שורת המקור, כמו Explained באתר: סוג · נכון ל- · איך זה חושב?\n  function meta(src) {\n    var p = el(\"p\", \"meta\");\n    if (!src) return p;\n    p.appendChild(document.createTextNode(src.kind + \" · \" + src.asOf + \" · \"));\n    if (siteLink(src.url)) p.appendChild(link(\"איך זה חושב?\", src.url));\n    return p;\n  }\n\n  function render(a) {\n    root.textContent = \"\";\n    var card = el(\"article\", \"card\");\n    card.setAttribute(\"dir\", \"rtl\");\n    card.appendChild(el(\"p\", \"site\", \"בחירות 2026 — ניתוח\"));\n    card.appendChild(el(\"h2\", \"title\", a.title));\n    if (a.summary) card.appendChild(el(\"p\", \"summary\", a.summary));\n    (a.sections || []).forEach(function (s) {\n      var sec = el(\"section\", \"sec\");\n      if (s.heading) sec.appendChild(el(\"h3\", \"heading\", s.heading));\n      if (s.kind === \"text\") {\n        String(s.text).split(/\\n+/).forEach(function (line) { sec.appendChild(el(\"p\", \"text\", line)); });\n      } else if (s.kind === \"list\") {\n        var ul = el(s.ordered ? \"ol\" : \"ul\", \"list\");\n        (s.items || []).forEach(function (it) { ul.appendChild(el(\"li\", null, it)); });\n        sec.appendChild(ul);\n      } else if (s.kind === \"table\") {\n        var wrap = el(\"div\", \"tablewrap\");\n        var table = el(\"table\", \"table tabular\");\n        var thead = el(\"thead\");\n        var hr = el(\"tr\");\n        (s.columns || []).forEach(function (c) { var th = el(\"th\", null, c); th.scope = \"col\"; hr.appendChild(th); });\n        thead.appendChild(hr);\n        table.appendChild(thead);\n        var tb = el(\"tbody\");\n        (s.rows || []).forEach(function (r) {\n          var tr = el(\"tr\");\n          r.forEach(function (c) { var td = el(\"td\", /\\d/.test(c) ? \"num\" : null); td.appendChild(el(\"bdi\", null, c)); tr.appendChild(td); });\n          tb.appendChild(tr);\n        });\n        table.appendChild(tb);\n        wrap.appendChild(table);\n        sec.appendChild(wrap);\n      } else if (s.kind === \"numbers\") {\n        var grid = el(\"div\", \"numbers\");\n        (s.items || []).forEach(function (n) {\n          var tile = el(\"div\", \"tile\");\n          tile.appendChild(el(\"p\", \"label\", n.label));\n          var v = el(\"p\", \"value tabular\");\n          v.appendChild(el(\"bdi\", null, n.value));\n          tile.appendChild(v);\n          tile.appendChild(meta(n.source));\n          grid.appendChild(tile);\n        });\n        sec.appendChild(grid);\n      }\n      if (s.source) sec.appendChild(meta(s.source));\n      card.appendChild(sec);\n    });\n    if (a.suggested_questions && a.suggested_questions.length) {\n      var q = el(\"div\", \"questions\");\n      q.appendChild(el(\"p\", \"qtitle\", \"שאלות להמשך\"));\n      a.suggested_questions.forEach(function (text) {\n        var b = el(\"button\", \"chip\", text);\n        b.type = \"button\";\n        b.addEventListener(\"click\", function () {\n          request(\"ui/message\", { role: \"user\", content: [{ type: \"text\", text: text }] }, 4000).catch(function () {\n            if (navigator.clipboard) navigator.clipboard.writeText(text).catch(function () {});\n            b.textContent = text + \" (הועתק — הדביקו בשיחה)\";\n          });\n        });\n        q.appendChild(b);\n      });\n      card.appendChild(q);\n    }\n    var foot = el(\"footer\", \"foot\");\n    if (a.footnote) foot.appendChild(el(\"p\", \"footnote\", a.footnote));\n    foot.appendChild(link(\"מעבר לאתר\", SITE));\n    card.appendChild(foot);\n    root.appendChild(card);\n    rendered = true;\n  }\n\n  function onResult(params) {\n    var sc = params && params.structuredContent;\n    if (params && params.isError) return; // ניסיון שנדחה — המודל מתקן ושולח שוב; מציגים רק את התשובה הסופית\n    if (sc && sc.answer && sc.answer.title) render(sc.answer);\n  }\n\n  window.addEventListener(\"message\", function (ev) {\n    if (ev.source !== window.parent) return;\n    var m = ev.data || {};\n    if (m.jsonrpc !== \"2.0\") return;\n    if (!m.method && typeof m.id === \"number\" && pending[m.id]) {\n      var cb = pending[m.id];\n      delete pending[m.id];\n      cb(m.error ? new Error(m.error.message || \"error\") : null, m.result);\n      return;\n    }\n    switch (m.method) {\n      case \"ui/notifications/tool-result\": onResult(m.params); return;\n      case \"ui/notifications/host-context-changed\": setTheme(m.params); return;\n      case \"ui/notifications/tool-input\": case \"ui/notifications/tool-input-partial\": case \"ui/notifications/tool-cancelled\": return;\n      case \"ui/resource-teardown\": post({ id: m.id, result: {} }); return;\n      case \"ping\": post({ id: m.id, result: {} }); return;\n      default: if (m.method && m.id !== undefined) post({ id: m.id, error: { code: -32601, message: \"Method not found\" } });\n    }\n  });\n\n  // הגובה האמיתי של התוכן, כדי שהמארח יתאים את המסגרת (בלי גלילה פנימית)\n  var last = -1;\n  function size() {\n    var h = Math.ceil(document.documentElement.scrollHeight);\n    if (h !== last) { last = h; post({ method: \"ui/notifications/size-changed\", params: { width: document.documentElement.scrollWidth, height: h } }); }\n  }\n  if (window.ResizeObserver) new ResizeObserver(size).observe(document.body);\n\n  request(\"ui/initialize\", { appInfo: { name: \"elections26-answer-card\", version: \"1.0.0\" }, appCapabilities: { availableDisplayModes: [\"inline\"] }, protocolVersion: \"2026-01-26\" })\n    .then(function (res) { setTheme(res.hostContext); post({ method: \"ui/notifications/initialized\" }); size(); })\n    .catch(function () {});\n  // לבדיקה בדפדפן: ?demo מציג תשובה לדוגמה\n  if (window.__DEMO__) render(window.__DEMO__);\n  void rendered;\n})();\n</script></body></html>";
